INSERT INTO `activity` VALUES (1,'周末环城骑行','骑行','本周末环城骑行活动，路线约50公里，适合新手参加。集合地点：朝阳公园东门，出发时间早上8点。','2024-12-14 08:00:00','北京市朝阳公园东门集合',30,1,'张三','13800138001','2025-12-12 06:02:05','2025-12-26 02:56:49',NULL,NULL,NULL),(2,'摩托车安全驾驶培训','培训','专业教练指导，提升安全驾驶技能。包含理论学习和实操训练，全天课程。','2024-12-20 09:00:00','俱乐部训练场',20,2,'李四','13800138002','2025-12-12 06:02:05','2025-12-12 06:02:05',NULL,NULL,NULL),(3,'年终聚会','聚会','俱乐部年终聚会，总结过去展望未来。晚餐+抽奖+表彰优秀会员。','2024-12-31 18:00:00','某某酒店3楼宴会厅',50,3,'王五','13800138003','2025-12-12 06:02:05','2025-12-12 06:02:05',NULL,NULL,NULL),(4,'山路技巧提升训练','培训','山路弯道技巧专项训练，提升压弯能力。封闭场地，专业教练指导。','2024-12-25 09:00:00','怀柔山区训练场',15,1,'赵六','13800138004','2025-12-12 06:02:05','2025-12-26 02:56:49',NULL,NULL,NULL),(2000452833663229954,'新手骑行入门培训','培训','适合刚拿驾照的新手，包含基础操作、起步刹车、安全知识、道路规则等内容。包含理论课程和实操训练。','2035-12-15 16:19:23','北京市朝阳区训练场',20,2,'张教练','13800138001','2025-12-15 06:28:16','2025-12-26 02:56:49',1001,NULL,NULL),(2000452834137186306,'进阶骑行技巧提升','培训','适合有一定骑行经验的骑友。包含弯道技巧、紧急避险、高速骑行、雨天骑行等高级技术训练。','2025-12-20 14:00:00','封闭场地',15,0,'李教练','13800138002','2025-12-15 06:28:16','2025-12-15 06:28:16',1002,NULL,NULL),(2000452834204295170,'摩托车日常保养维修','培训','教你自己动手进行日常保养：换机油、清洗链条、调整刹车、更换火花塞等基础维修技能。','2025-12-22 16:04:22','线上课程',2,2,'王师傅','13111111111','2025-12-15 06:28:16','2025-12-26 02:56:49',1003,NULL,NULL),(2000452834204295171,'安全骑行意识培训','培训','防御性驾驶理念、事故案例分析、应急处理技巧、装备选择等安全知识。支持线上学习。','2025-12-22 16:04:24','线上课程',0,0,'赵教练','13800138004','2025-12-15 06:28:16','2025-12-26 02:56:49',1004,NULL,NULL),(2000452834267209730,'山路弯道专项训练','培训','专注山路弯道技术：压弯技巧、视线管理、油门控制、重心转移等。封闭场地实操训练。','2025-12-21 09:00:00','怀柔山区训练场',12,1,'李教练','13800138002','2025-12-15 06:28:16','2025-12-15 06:28:16',1005,NULL,NULL),(2000452834334318593,'长途骑行准备课程','培训','长途骑行前的准备工作：路线规划、装备检查、体能准备、应急预案、团队协作等。','2025-12-22 16:04:26','线上课程',0,0,'陈教练','13800138005','2025-12-15 06:28:16','2025-12-15 06:28:16',1006,NULL,NULL),(2000452834334318594,'摩托车驾驶证考试辅导','培训','针对摩托车驾照考试的专项辅导，包含科目二科目三的技巧讲解和模拟练习。','2025-12-16 18:00:00','考场实地训练',10,0,'张教练','13800138001','2025-12-15 06:28:16','2025-12-15 06:28:16',1007,NULL,NULL),(2000452834397233153,'越野骑行技术培训','培训','越野摩托车骑行技术：站姿骑行、跳跃技巧、泥地控制、陡坡攀爬等专业训练。','2025-12-22 16:10:49','昌平越野训练场',3,3,'刘教练','13800138006','2025-12-15 06:28:17','2025-12-29 14:31:21',1008,NULL,NULL),(2027280531215581185,'横说竖说','骑行','6','2026-02-27 09:00:00','海港区和美小区',0,0,'','','2026-02-27 15:11:58','2026-02-27 15:19:30',NULL,39.976898,119.572573),(2027280701600792578,'氨基酸','培训','是','2036-02-27 15:12:39','海港区和美小区',0,0,'','','2026-02-27 15:12:38','2026-02-27 15:19:59',2027280701567238145,39.973599,119.577386);
