INSERT INTO `course` VALUES (1001,'新手骑行入门培训','新手入门','适合刚拿驾照的新手，包含基础操作、起步刹车、安全知识、道路规则等内容。包含理论课程和实操训练。',0,'每周三 19:00-21:00','2小时','张教练','北京市朝阳区训练场',NULL,20,'13800138001'),(1002,'进阶骑行技巧提升','进阶技巧','适合有一定骑行经验的骑友。包含弯道技巧、紧急避险、高速骑行、雨天骑行等高级技术训练。',0,'每周六 14:00-17:00','3小时','李教练','封闭场地',NULL,15,'13800138002'),(1003,'摩托车日常保养维修','保养维修','教你自己动手进行日常保养：换机油、清洗链条、调整刹车、更换火花塞等基础维修技能。',1,'线上随时学习','2小时','王师傅','线上课程',NULL,2,'13111111111'),(1004,'安全骑行意识培训','安全培训','防御性驾驶理念、事故案例分析、应急处理技巧、装备选择等安全知识。支持线上学习。',1,'线上随时学习','2小时','赵教练','线上课程',NULL,0,'13800138004'),(1005,'山路弯道专项训练','进阶技巧','专注山路弯道技术：压弯技巧、视线管理、油门控制、重心转移等。封闭场地实操训练。',0,'每周日 09:00-12:00','2小时','李教练','怀柔山区训练场',NULL,12,'13800138002'),(1006,'长途骑行准备课程','骑行技巧','长途骑行前的准备工作：路线规划、装备检查、体能准备、应急预案、团队协作等。',1,'线上随时学习','2小时','陈教练','线上课程',NULL,0,'13800138005'),(1007,'摩托车驾驶证考试辅导','新手入门','针对摩托车驾照考试的专项辅导，包含科目二科目三的技巧讲解和模拟练习。',0,'每周二/四 18:00-20:00','2小时','张教练','考场实地训练',NULL,10,'13800138001'),(1008,'越野骑行技术培训','越野技巧','越野摩托车骑行技术：站姿骑行、跳跃技巧、泥地控制、陡坡攀爬等专业训练。',0,'每月第一个周六 09:00-16:00','2小时','刘教练','昌平越野训练场',NULL,8,'13800138006'),(2013900912399724546,'131','安全培训','131',0,'','2小时','','',NULL,0,''),(2026916788434571266,'阿斯顿','进阶技巧','阿斯顿',0,'','2小时','','',NULL,0,''),(2026916903039733761,'阿斯顿啊','骑行技巧','阿斯顿',0,'','2小时','','',NULL,0,''),(2026922238513233921,'阿斯顿','骑行技巧','阿斯顿',0,'','2小时','','',NULL,0,''),(2027280701567238145,'氨基酸','新手入门','是',0,'','2小时','','',NULL,0,'');
/*!40000 ALTER TABLE `course` ENABLE KEYS */;
