DROP TABLE IF EXISTS `member`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `member` (
  `id` bigint NOT NULL COMMENT '会员ID',
  `user_id` bigint NOT NULL COMMENT '关联用户ID',
  `member_name` varchar(50) NOT NULL COMMENT '会员姓名',
  `phone` varchar(11) NOT NULL COMMENT '手机号',
  `id_card` varchar(18) DEFAULT NULL COMMENT '身份证号',
  `gender` varchar(10) DEFAULT '男' COMMENT '性别：男/女',
  `join_date` date NOT NULL COMMENT '加入日期',
  `motorcycle_brand` varchar(50) DEFAULT NULL COMMENT '摩托车品牌',
  `motorcycle_model` varchar(50) DEFAULT NULL COMMENT '摩托车型号',
  `plate_number` varchar(20) DEFAULT NULL COMMENT '车牌号',
  `address` varchar(200) DEFAULT NULL COMMENT '联系地址',
  `remark` text COMMENT '备注',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_phone` (`phone`),
  UNIQUE KEY `uk_user_id` (`user_id`),
  KEY `idx_member_name` (`member_name`),
  CONSTRAINT `fk_member_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='会员信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

