--
-- Table structure for table `news`
--

DROP TABLE IF EXISTS `news`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `news` (
  `id` bigint NOT NULL,
  `news_name` varchar(20) NOT NULL COMMENT '新闻名称（不超过20字）',
  `news_content` varchar(200) NOT NULL COMMENT '新闻内容（不超过200字）',
  `news_category` varchar(255) NOT NULL COMMENT '新闻分类（多选，逗号分隔）',
  `news_description` text NOT NULL COMMENT '新闻描述',
  `has_image` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否有图片（1=有，0=无）',
  `image_url` varchar(500) DEFAULT NULL COMMENT '图片URL',
  `news_tags` varchar(255) NOT NULL COMMENT '新闻标签（多选，逗号分隔）',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除（1=已删除，0=正常）',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `status` varchar(20) DEFAULT 'pending' COMMENT '状态：pending待审核/approved已通过/rejected已拒绝',
  `creator_id` bigint DEFAULT NULL COMMENT '创建者ID',
  `creator_name` varchar(50) DEFAULT NULL COMMENT '创建者姓名',
  PRIMARY KEY (`id`),
  KEY `idx_news_name` (`news_name`),
  KEY `idx_deleted` (`deleted`),
  KEY `idx_create_time` (`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='新闻信息表';
/*!40101 SET character_set_client = @saved_cs_client */;

