LOCK TABLES `news` WRITE;
/*!40000 ALTER TABLE `news` DISABLE KEYS */;
INSERT INTO `news` VALUES (1,'春季环湖骑行活动圆满结束','4月15日，俱乐部组织的春季环湖骑行活动圆满结束。本次活动共有58名会员参与，全程120公里，途经东湖、西山、北岭等多个风景名胜。活动中大家互相帮助，展现了良好的团队协作精神。多位新会员表示通过活动更好地融入了俱乐部大家庭。','俱乐部活动,最新动态','58名会员参与，全程120公里，团队协作精神突出',1,'HBBTJ/news/images/440fb426-d441-4f68-8389-caa20176985a.jpg','活动,动态',0,'2025-12-10 07:58:32','2026-01-26 16:12:22','approved',NULL,NULL),(2,'川藏线长途骑行队凯旋归来','经过15天的长途骑行，俱乐部川藏线骑行队全员安全返回。12名队员克服高原反应、恶劣天气等困难，成功完成2400公里的挑战。队长张明表示：\"这次经历让我们更加热爱骑行，也见证了团队的力量。\"俱乐部将在下周举办分享会，欢迎大家参加。','俱乐部活动,最新动态','15天2400公里，12名队员挑战川藏线成功',1,'HBBTJ/news/images/a71b5472-2e57-4dae-8469-15c8ca8ae619.jpg','活动,推荐',0,'2025-12-10 07:58:32','2026-01-26 16:18:18','approved',NULL,NULL),(3,'俱乐部年度骑行大赛报名启动','2025年度\"极速挑战\"骑行大赛将于6月举行。比赛设置竞速赛、耐力赛、技巧赛三个项目，欢迎各级别会员报名参加。冠军将获得价值5000元的改装基金和年度荣誉勋章。报名截止日期为5月20日，名额有限，先到先得！','俱乐部活动','年度骑行大赛，冠军奖励5000元改装基金',1,'HBBTJ/news/images/c77d292a-339a-41a4-b7a2-030299091e4e.jpg','活动,推荐',0,'2025-12-10 07:58:32','2026-01-26 16:18:40','approved',NULL,NULL),(4,'会员突破500人里程碑达成','截至本月，俱乐部注册会员已突破500人大关！从最初的十几个人到如今的大家庭，感谢每一位骑友的支持和信任。为庆祝这一里程碑，俱乐部将举办会员答谢活动，所有会员享受培训课程8折优惠。我们将继续提供更优质的服务和活动。','俱乐部活动,最新动态','会员突破500人，举办答谢活动和优惠',1,'HBBTJ/news/images/6564073a-8abe-4c12-ad58-1b0d1383ddfc.jpg','动态',0,'2025-12-10 07:58:32','2026-01-26 16:18:47','approved',NULL,NULL),(5,'山路压弯技巧实战分享','资深教练李华分享山路骑行压弯技巧：①入弯前降速至合适档位；②视线提前看向出弯点；③车身倾斜角度要循序渐进；④出弯时平稳加油门。他强调\"慢进快出\"的原则，建议新手先在封闭场地练习基本功。下周六将开设专项训练营，欢迎报名。','骑行技巧,最新动态','压弯四大要点，新手必看的实战技巧',1,'HBBTJ/news/images/de280a7e-3d26-43d8-97cd-0151612e1f3a.jpg','教学,推荐',0,'2025-12-10 07:58:32','2026-01-26 16:18:54','approved',NULL,NULL),(6,'雨天骑行安全指南发布','雨季来临，俱乐部发布雨天骑行安全指南：①降低车速，保持安全距离；②避免急刹车和大幅度转向；③优先选择排水良好的路段；④穿着防水骑行服，确保视野清晰；⑤积水路段谨慎通过。教练组提醒：能见度低于50米时建议暂停骑行。','骑行技巧,安全知识','雨天骑行五大要点，保障安全第一',1,'HBBTJ/news/images/9585429f-6ff6-4443-95bb-ae7ac1aa69bd.jpg','安全,教学',0,'2025-12-10 07:58:32','2026-01-26 16:19:02','approved',NULL,NULL),(7,'长途骑行装备清单推荐','计划长途骑行？这份装备清单请收好：①必备：头盔、手套、骑行服、护具；②工具：补胎工具、扳手组、备用零件；③应急：急救包、应急食品、充电宝；④导航：GPS设备或手机支架。教练建议提前规划路线，每骑行2小时休息15分钟。','骑行技巧','长途骑行必备装备清单和注意事项',1,'HBBTJ/news/images/77a7b524-101a-41fc-ba7a-3420386903dd.jpg','教学',0,'2025-12-10 07:58:32','2026-01-26 16:19:09','approved',NULL,NULL),(8,'高速公路骑行安全规范','俱乐部安全部发布高速公路骑行规范：①排量250cc以上车辆方可上高速；②速度保持在60-100km/h；③禁止占用应急车道；④保持车距，避免长时间骑行；⑤夜间骑行需开启示廓灯。违规骑行不仅危险，还将面临扣分罚款。','安全知识,最新动态','高速公路骑行五大规范，安全第一',1,'HBBTJ/news/images/ecb058b9-4d85-44a8-b699-2d98ee967376.jpg','安全,教学',0,'2025-12-10 07:58:32','2026-01-26 16:19:28','approved',NULL,NULL),(9,'防御性驾驶理念培训通知','本周六下午3点，俱乐部将举办防御性驾驶理念培训。课程内容包括：①预判其他车辆行为；②保持安全车距；③避免盲区骑行；④应对突发情况的技巧。培训免费，提供培训证书。名额仅限50人，请提前在群内报名。','安全知识','防御性驾驶培训，提升安全意识',1,'HBBTJ/news/images/25a3ac36-7b4b-49be-af14-65bc82d6b4e0.jpg','安全,动态',0,'2025-12-10 07:58:32','2026-01-26 16:19:38','approved',NULL,NULL),(10,'夏季高温骑行注意事项','夏季高温天气骑行需特别注意：①选择透气性好的骑行服；②随身携带充足的水分；③避开中午12点至下午3点的高温时段；④定期检查轮胎胎压；⑤感到头晕乏力应立即停车休息。教练提醒：中暑是夏季骑行的主要风险之一。','安全知识,最新动态','夏季骑行五大注意事项和应急措施',1,'HBBTJ/news/images/08f0fd3e-0b6e-40aa-8243-eee595bcdb7d.jpg','安全',0,'2025-12-10 07:58:32','2026-01-26 16:19:45','approved',NULL,NULL),(11,'摩托车日常保养基础教程','教练手把手教你日常保养：①每500公里检查链条松紧度并润滑；②每1000公里更换机油和滤芯；③定期清洁空气滤清器；④检查刹车片磨损情况；⑤轮胎气压保持标准值。本周日上午10点开设实操课程，自带工具即可参加。','车辆保养','日常保养五步法，延长爱车寿命',1,'HBBTJ/news/images/d582b002-0c48-43e3-bc8f-94d636a92d3e.jpg','保养,教学',0,'2025-12-10 07:58:32','2026-01-26 16:19:54','approved',NULL,NULL),(12,'换季保养专项服务优惠','春季换季保养套餐限时优惠！包含：①全车深度清洁；②机油机滤更换；③链条调整润滑；④刹车系统检查；⑤电瓶检测。原价680元，会员价仅需480元。活动截止到本月底，预约请联系服务部。提供免费上门取车服务。','车辆保养,最新动态','换季保养套餐，会员专享优惠价480元',1,'HBBTJ/news/images/7f8347c1-ea0b-40c3-8a36-ec8eb7c15e28.jpg','保养,动态',0,'2025-12-10 07:58:32','2026-01-26 16:20:07','approved',NULL,NULL),(13,'会员改装案例：川崎Z900改装分享','会员王强分享他的川崎Z900改装经历：更换阿克拉波维奇排气、升级欧林斯避震、安装防摔部件、改装LED灯组。总投入约3万元，动力提升明显，操控更加精准。他强调：\"改装需合法合规，优先考虑安全性。\"俱乐部将在下月举办改装展示会。','会员风采','川崎Z900改装案例，3万元打造性能利器',1,'HBBTJ/news/images/35fb3b6c-8c12-4593-ada0-4aa054f5db2c.jpg','推荐',0,'2025-12-10 07:58:32','2026-01-26 16:20:15','approved',NULL,NULL),(14,'新会员入会体验分享','新会员李明分享入会感受：\"加入俱乐部一个月，参加了两次骑行活动和一次技巧培训，收获满满。教练很专业，会员很热情，真正感受到了大家庭的温暖。特别是新手训练营，让我从菜鸟变成了敢上路的骑手。强烈推荐给刚拿驾照的朋友！\"','会员风采,最新动态','新会员真实体验，从菜鸟到独立骑手',1,'HBBTJ/news/images/c417ed6b-d698-4b9e-b6d1-0994fedd48ef.jpg','动态,推荐',0,'2025-12-10 07:58:32','2026-02-12 09:00:05','approved',NULL,NULL),(15,'新手训练营第五期火热招生','针对刚拿到驾照的新手，推出为期一周的封闭式训练营。课程包含：①基础操作（起步、换挡、刹车）；②安全意识培养；③道路规则讲解；④实际路况模拟。资深教练一对一指导，提供训练车辆，包教包会！现在报名享受早鸟价8折优惠。','最新动态','新手训练营招生，资深教练一对一指导',1,'https://picsum.photos/id/22/360/180','动态,教学',1,'2025-12-10 07:58:32','2025-12-10 08:04:07','approved',NULL,NULL),(2016072349445173249,'123','123','骑行技巧','123',1,'HBBTJ/news/images/6dfbf510-233f-47ad-be8a-af93509a67bd.jpg','教学',1,'2026-01-27 16:54:39','2026-01-28 11:10:36','pending',1993863963056218113,'admin'),(2016348046336167938,'11','11','俱乐部活动','11',1,'HBBTJ/news/images/d12e2978-626b-4b41-a936-3228918d9603.jpg','活动',1,'2026-01-28 11:10:10','2026-01-28 11:10:10','pending',1993863963056218113,'admin'),(2017047097197072385,'11','11','骑行技巧','11',1,'HBBTJ/news/images/9843bc5d-1d91-4b68-9cac-2835002c97ad.jpg','活动',1,'2026-01-30 09:27:57','2026-01-30 09:27:57','pending',1993863963056218113,'admin'),(2017048523172466689,'11','11','骑行技巧','11',1,'HBBTJ/news/images/d4aab2b4-1d26-4cc4-a599-a2018f8c906e.jpg','教学',1,'2026-01-30 09:33:37','2026-01-30 09:34:15','pending',1993863963056218113,'admin'),(2017051274883354626,'22','22','骑行技巧','22',1,'HBBTJ/news/images/7ca5f8cd-e634-4d78-8a59-d4bdedeb8261.jpg','教学',1,'2026-01-30 09:44:33','2026-01-30 09:44:33','pending',1993863963056218113,'admin'),(2017102825064755202,'33','33','骑行技巧','33',1,'HBBTJ/news/images/c61b8923-be19-4b53-b1d4-3f78dd68e385.jpg','活动',1,'2026-01-30 13:09:24','2026-01-30 13:09:24','approved',1993863963056218113,'admin'),(2021767359025000449,'44','44','俱乐部活动','44',1,'HBBTJ/news/images/12de298f-89b5-4f30-bbde-c009ed3670bf.jpg','动态',1,'2026-02-12 10:04:35','2026-02-12 10:04:35','rejected',2004101284879872001,'Vip'),(2021768491646464001,'55','55','俱乐部活动','55',1,'HBBTJ/news/images/715d153e-c45a-4d52-8b52-e31ca6b5e3dc.jpg','动态',1,'2026-02-12 10:09:05','2026-02-12 10:09:05','rejected',1993863963056218113,'admin'),(2021869012545884162,'66','66','俱乐部活动','66',1,'HBBTJ/news/images/616ccd44-c423-4fe8-9519-652a05cc063a.jpg','动态',1,'2026-02-12 16:48:31','2026-02-12 16:48:31','rejected',2004101284879872001,'Vip'),(2026835308081553409,'123','123','骑行技巧','123',0,'','动态',1,'2026-02-26 09:42:48','2026-02-26 09:42:48','pending',2004101284879872001,'Vip'),(2026922373272027137,'啊','啊','骑行技巧','啊',0,'','动态',1,'2026-02-26 15:28:46','2026-02-26 15:28:46','rejected',2004101284879872001,'Vip'),(2027187889827987458,'1','1','俱乐部活动','1',0,'','动态',1,'2026-02-27 09:03:50','2026-02-27 09:03:50','rejected',2004101284879872001,'Vip');
